import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:hive/hive.dart';
import 'package:lifeplan/main.dart';
import 'package:lifeplan/models/goal.dart';
import 'package:lifeplan/models/frequency.dart';
import 'package:lifeplan/models/backup_settings.dart';
import 'package:lifeplan/services/database_service.dart';

void main() {
  late Directory tempDir;

  setUpAll(() async {
    // 1. Configurar directorio temporal para Hive
    tempDir = await Directory.systemTemp.createTemp('lifehabit_widget_test_');
    Hive.init(tempDir.path);

    // 2. Registrar adaptadores
    if (!Hive.isAdapterRegistered(0)) {
      Hive.registerAdapter(GoalAdapter());
    }
    if (!Hive.isAdapterRegistered(1)) {
      Hive.registerAdapter(FrequencyAdapter());
    }
    if (!Hive.isAdapterRegistered(2)) {
      Hive.registerAdapter(BackupSettingsAdapter());
    }
  });

  tearDownAll(() async {
    // Limpiar archivos de Hive y cerrar
    await Hive.close();
    if (await tempDir.exists()) {
      await tempDir.delete(recursive: true);
    }
  });

  testWidgets('LifePlanApp renders correctly', (WidgetTester tester) async {
    // Abrir las cajas necesarias antes de renderizar la app
    final goalsBox = await Hive.openBox<Goal>('goals');
    await Hive.openBox<BackupSettings>('backup_settings');

    // Inicializar DatabaseService con el box abierto
    DatabaseService.initializeForTest(goalsBox);

    await tester.pumpWidget(const LifePlanApp());

    // Usar pump con duración en lugar de pumpAndSettle para evitar esperas infinitas
    // debidas a animaciones o procesos en segundo plano (como el backup).
    await tester.pump(const Duration(milliseconds: 500));
    await tester.pump(const Duration(milliseconds: 500));

    // Verificar que el título de la app se muestra en el AppBar
    expect(find.text('LifePlan'), findsWidgets);

    // Cerrar cajas al final del test
    await Hive.close();
  });
}

